import{_ as r,C as o,o as a,c as d,j as t,a as s,b as l,w as n,E as c,a3 as p,a2 as h}from"./chunks/framework.CZqXuAiL.js";const P=JSON.parse('{"title":"Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/architecture/pipeline.md","filePath":"openshield-xdp/architecture/pipeline.md","lastUpdated":null}'),g={name:"openshield-xdp/architecture/pipeline.md"};function k(y,e,u,E,b,D){const i=o("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t("h1",{id:"pipeline",tabindex:"-1"},[s("Pipeline "),t("a",{class:"header-anchor",href:"#pipeline","aria-label":'Permalink to "Pipeline"'},"​")],-1)),e[2]||(e[2]=t("p",null,[s("OpenShield-XDP processes every packet through a fixed "),t("strong",null,"16-stage pipeline"),s(". Each stage is a discrete check; any stage can drop the packet ("),t("code",null,"XDP_DROP"),s("). Once a packet passes all stages, it is passed to the kernel ("),t("code",null,"XDP_PASS"),s(").")],-1)),e[3]||(e[3]=t("h2",{id:"pipeline-order",tabindex:"-1"},[s("Pipeline Order "),t("a",{class:"header-anchor",href:"#pipeline-order","aria-label":'Permalink to "Pipeline Order"'},"​")],-1)),(a(),l(p,null,{default:n(()=>[c(i,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%F0%9F%93%A6%20Packet%20Arrives%22%5D%20--%3E%20B%5B%220.%20MAC%20Filter%3Cbr%2F%3EL2%20blacklist%2Fwhitelist%22%5D%0A%20%20%20%20B%20--%3E%7C%22drop%22%7C%20D1%5B%22%E2%9D%8C%20DROP%22%5D%0A%20%20%20%20B%20--%3E%7C%22pass%22%7C%20C%5B%221.%20Packet%20Parse%3Cbr%2F%3EEthernet%2C%20VLAN%20x2%2C%20IPv4%2FIPv6%2C%20L4%22%5D%0A%20%20%20%20C%20--%3E%20D2%7B%22Malformed%3F%22%7D%0A%20%20%20%20D2%20--%3E%7C%22yes%22%7C%20D3%5B%22%E2%9D%8C%20DROP%22%5D%0A%20%20%20%20D2%20--%3E%7C%22no%22%7C%20E%7B%222.%20SYNPROXY%3Cbr%2F%3Escalar%20gate%20%C2%B7%20kernel%20%E2%89%A5%205.15%22%7D%0A%20%20%20%20E%20--%3E%7C%22pass%20(rate-based%20ban%20later)%22%7C%20F%5B%223.%20Panic%20Breaker%3Cbr%2F%3Eper-CPU%20probabilistic%20drop%22%5D%0A%20%20%20%20F%20--%3E%7C%22drop%22%7C%20D5%5B%22%E2%9D%8C%20DROP%22%5D%20%20%0A%20%20%20%20F%20--%3E%7C%22pass%22%7C%20G%7B%224.%20Global%20Detection%3Cbr%2F%3Ekernel%20%E2%89%A5%206.10%22%7D%0A%20%20%20%20G%20--%3E%20H%5B%225.%20Bloom%20Whitelist%3Cbr%2F%3E150K%20entries%2C%20k%3D3%20hash%22%5D%0A%20%20%20%20H%20--%3E%7C%22miss%22%7C%20I%5B%226.%20HASH%20Whitelist%3Cbr%2F%3Eper-IP%20bypass%20flags%22%5D%0A%20%20%20%20I%20--%3E%7C%22bypass%22%7C%20P%5B%22%E2%9C%85%20XDP_PASS%22%5D%0A%20%20%20%20I%20--%3E%7C%22no%22%7C%20J%7B%227.%20Ban%20Check%3Cbr%2F%3Esingle-IP%20%2B%20LPM%20subnet%22%7D%0A%20%20%20%20J%20--%3E%7C%22banned%22%7C%20D6%5B%22%E2%9D%8C%20DROP%22%5D%0A%20%20%20%20J%20--%3E%7C%22pass%22%7C%20K%7B%228.%20Validation%3Cbr%2F%3Ebogon%2C%20bogus%20TCP%2C%20L4%20bounds%22%7D%0A%20%20%20%20K%20--%3E%7C%22fail%22%7C%20D7%5B%22%E2%9D%8C%20DROP%22%5D%0A%20%20%20%20K%20--%3E%7C%22pass%22%7C%20L%7B%229.%20UDP%20Amplification%3Cbr%2F%3EDNS%20QR-bit%20%2B%208-port%20generic%22%7D%0A%20%20%20%20L%20--%3E%7C%22yes%22%7C%20D8%5B%22%E2%9D%8C%20DROP%22%5D%0A%20%20%20%20L%20--%3E%7C%22no%22%7C%20M%7B%2210.%20L7%20Signatures%3Cbr%2F%3E16%20pattern%20rules%22%7D%0A%20%20%20%20M%20--%3E%7C%22match%22%7C%20D9%5B%22%E2%9D%8C%20DROP%22%5D%0A%20%20%20%20M%20--%3E%7C%22no%22%7C%20N%5B%2211.%20IP%20Stats%20%2B%20New-Source%3Cbr%2F%3Erate%20counters%2C%20flood%20detection%22%5D%0A%20%20%20%20N%20--%3E%20O%7B%2212.%20Rate%20Limiting%3Cbr%2F%3Ethreshold%20or%20token%20bucket%22%7D%0A%20%20%20%20O%20--%3E%7C%22exceeded%22%7C%20D10%5B%22%E2%9D%8C%20DROP%22%5D%0A%20%20%20%20O%20--%3E%7C%22pass%22%7C%20P%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=h(`<div class="tip custom-block"><p class="custom-block-title">Legend</p><p>🟢 Green = early fast-pass / bookkeeping   🔵 Blue = validation   🟣 Purple = feature-gated   🔴 Red = detection   🟠 Orange = freplace-able stage</p></div><h2 id="stage-reference" tabindex="-1">Stage Reference <a class="header-anchor" href="#stage-reference" aria-label="Permalink to &quot;Stage Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Stage</th><th>Action</th><th style="text-align:center;">Freplace?</th><th style="text-align:center;">Feature Gate</th></tr></thead><tbody><tr><td>0</td><td><strong>MAC Filter</strong></td><td>Whitelist/blacklist by source MAC address (8-slot config). Drops immediately before any IP parsing.</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>1</td><td><strong>Parse</strong></td><td>Extract Ethernet, IP, and L4 headers into <code>struct packet_info</code>. Bails out on non-IP or malformed packets.</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>2</td><td><strong>SYNPROXY</strong></td><td>Scalar, non-terminal SYN gate. Reads pre-parsed scalars only (no packet access, no helpers); accounts SYNs and continues. Flood mitigation is delivered by the per-IP <code>syn_pps_threshold</code> rate limiter.</td><td style="text-align:center;">—</td><td style="text-align:center;"><code>OPENSHIELD_SYNPROXY</code> (≥ 5.15)</td></tr><tr><td>3</td><td><strong>Panic Breaker</strong></td><td>Per-CPU packet rate check with probabilistic drop. When a CPU exceeds <code>panic_pps_rate</code>, drops <code>panic_drop_ratio</code>% of packets.</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>4</td><td><strong>Global Detection</strong></td><td>Window-based entropy spoofing detection + SYN/FIN ratio anomaly check. Drops when source IP entropy is high (spoofed flood) or SYN:FIN ratio exceeds threshold.</td><td style="text-align:center;">—</td><td style="text-align:center;"><code>OPENSHIELD_GLOBAL_DETECT</code> (≥ 6.10)</td></tr><tr><td>5</td><td><strong>Bloom Whitelist</strong></td><td>Fast negative-check: if the Bloom filter says &quot;definitely not present&quot;, skip the expensive HASH whitelist lookup. Saves ~60-100ns/pkt.</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>6</td><td><strong>HASH Whitelist</strong></td><td>Exact-match lookup in <code>whitelist_map</code> (IPv4) or <code>whitelist_map_v6</code> (IPv6). <code>WL_FULL_BYPASS</code> entries skip all further checks. Other flags disable specific stages (<code>WL_SKIP_BAN</code>, <code>WL_SKIP_VALIDATION</code>, <code>WL_SKIP_RATE</code>).</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>7</td><td><strong>Ban Check</strong></td><td>Lookup in <code>ban_map</code> + fallthrough to <code>subnet_ban_map</code> (LPM_TRIE) for CIDR bans. Also checks <code>prefix_ban_map</code> for auto-escalation.</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td>8</td><td><strong>Source Validation</strong></td><td>Private/bogon IP filtering (<code>10.0.0.0/8</code>, <code>127.0.0.0/8</code>, etc). Controlled by <code>enable_private_filter</code>.</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>9</td><td><strong>L4 Validation</strong></td><td>TCP flag sanity (<code>enable_bogus_tcp_filter</code>) and L4 bounds check (<code>enable_malformed_filter</code>). Drops SYN+FIN, null flags, and truncated L4 payloads.</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>10</td><td><strong>UDP Amplification</strong></td><td>Detects amplified DNS responses (<code>sport=53, QR=1, large payload</code>) and generic UDP reflection on configurable ports (8 slots).</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td>11</td><td><strong>L7 Signatures</strong></td><td>Byte-pattern matching at configurable offsets. All 16 signature slots are always checked (single unrolled loop; no kernel gate).</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td>12</td><td><strong>IP Stats Lookup</strong></td><td>Lookup or create <code>ip_stats</code> entry. New IPs get a fresh stats struct with token bucket pre-filled.</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>13</td><td><strong>New-Source Flood</strong></td><td>If the global new-source creation rate exceeds <code>new_source_limit</code>, bans new IPs for <code>new_source_ban_duration_sec</code>. Uses spinlock-protected <code>new_source_map</code>.</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>14</td><td><strong>Connection Tracking</strong></td><td>Detects blind TCP ACK/RST floods by tracking <code>last_syn_seen_ns</code>. Drops non-SYN TCP packets from IPs that haven&#39;t sent a SYN within <code>ct_syn_timeout_sec</code>.</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td>15</td><td><strong>Window Reset</strong></td><td>1-second sliding window: resets per-second counters, decays suspicion scores, runs advanced per-window checks (TTL anomaly, packet size anomaly, connection rate).</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td>16</td><td><strong>Rate Limiting</strong></td><td>Either threshold-scoring mode (adds to <code>suspicion_score</code> per violation) or token-bucket mode. Bans IPs exceeding <code>suspicion_threshold</code>.</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr></tbody></table><h2 id="feature-gated-stages" tabindex="-1">Feature-Gated Stages <a class="header-anchor" href="#feature-gated-stages" aria-label="Permalink to &quot;Feature-Gated Stages&quot;">​</a></h2><p>Some stages are compile-time gated based on the running kernel version. Note the L7 signature matcher is <strong>not</strong> gated — all 16 slots are always compiled and load on every supported kernel.</p><h3 id="synproxy-openshield-synproxy-—-scalar-all-supported-kernels" tabindex="-1">SYNPROXY (<code>OPENSHIELD_SYNPROXY</code> — scalar, all supported kernels) <a class="header-anchor" href="#synproxy-openshield-synproxy-—-scalar-all-supported-kernels" aria-label="Permalink to &quot;SYNPROXY (\`OPENSHIELD_SYNPROXY\` — scalar, all supported kernels)&quot;">​</a></h3><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifdef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OPENSHIELD_SYNPROXY</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    /* Scalar-only, non-terminal SYN gate. Reads ONLY pre-parsed scalar fields</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     * (no packet-pointer access, no version-specific helpers) so it verifies</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     * and loads on every kernel 5.15 → latest with zero user fixes. Actual SYN</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     * flood mitigation is delivered by the per-IP syn_pps_threshold rate</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     * limiter in the rate-limiting stage. */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">synproxy_check_listener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, cfg) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> STAGE_DROP)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> XDP_DROP;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span></code></pre></div><p>The baseline gate never drops — it accounts SYNs for profiling and continues. On kernels ≥ 6.10 it provides a hook that an <strong>opt-in</strong> freplace module can hot-patch to add richer listener verification (<code>bpf_sk_lookup_tcp</code>). Below kernel 5.15 the block compiles away entirely.</p><h3 id="global-detection-entropy-openshield-global-detect-openshield-entropy-—-kernel-≥-6-10" tabindex="-1">Global Detection &amp; Entropy (<code>OPENSHIELD_GLOBAL_DETECT</code>, <code>OPENSHIELD_ENTROPY</code> — kernel ≥ 6.10) <a class="header-anchor" href="#global-detection-entropy-openshield-global-detect-openshield-entropy-—-kernel-≥-6-10" aria-label="Permalink to &quot;Global Detection &amp; Entropy (\`OPENSHIELD_GLOBAL_DETECT\`, \`OPENSHIELD_ENTROPY\` — kernel ≥ 6.10)&quot;">​</a></h3><p>SYN/FIN ratio detection, entropy-based spoof detection, and per-packet entropy bucket tracking are gated at kernel 6.10. Below 6.10 these blocks compile away; the rest of the pipeline (including all 16 L7 signature slots) is unaffected.</p><div class="warning custom-block"><p class="custom-block-title">Kernel Version Detection</p><p>The Makefile detects the running kernel via <code>uname -r</code> at build time. Feature gates are <strong>compile-time only</strong> — you must rebuild after a kernel upgrade to enable new features. See <a href="./kernel-gates">Kernel Feature Gates</a> for details.</p></div><h2 id="early-exit-optimization" tabindex="-1">Early-Exit Optimization <a class="header-anchor" href="#early-exit-optimization" aria-label="Permalink to &quot;Early-Exit Optimization&quot;">​</a></h2><p>The pipeline is organized for maximum early-drop efficiency:</p><ol><li><strong>MAC filter</strong> runs before any IP parsing — no packet metadata needed</li><li><strong>SYNPROXY</strong> runs immediately after parse — SYN floods are the most common attack</li><li><strong>Panic breaker</strong> protects CPU before expensive per-IP lookups</li><li><strong>Bloom filter</strong> skips expensive HASH whitelist lookup for non-whitelisted IPs</li><li><strong><code>bans_empty</code> / <code>whitelist_empty</code></strong> flags skip entire lookup blocks when maps are empty</li></ol>`,14))])}const m=r(g,[["render",k]]);export{P as __pageData,m as default};
